---@field Img_Charactor                 	Engine.UI.ImageAlterable
local UIBattleEndLeftPanel = Class("UIBattleEndLeftPanel")

------------ LifeCycle ------------

function UIBattleEndLeftPanel:__init()
    self.showData = nil
end

function UIBattleEndLeftPanel:__delete()
    self.showData = nil
end

function UIBattleEndLeftPanel:Awake()
end

function UIBattleEndLeftPanel:Start()
end

function UIBattleEndLeftPanel:OnDestroy()
    self.controller = nil
    --luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

------------ LifeCycle ------------

---ShowPanel
---展示面板
---@param data table
function UIBattleEndLeftPanel:ShowPanel(data)
    self.showData = data
    local questId = UIBattlingDataMgr:GetQuestId()
    local showType = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests) -- 关卡类型
    local passState = data.isPassed -- 战斗结果
    --- 人物镜头
    local isShowRole = BattleEndMgr:GetPanelShowType(passState, showType, self.showData.response)
    if isShowRole then
        BattleEndMgr:BattleEndShow()
    end
    --- 玩家经验
    local isShowEXP = BattleEndMgr:ShowPlayerEXP(passState, showType)
    if isShowEXP then
        self:SetPlayerExpChangeShow()
    end
    --self:ShowType(showType, passState)
    self:PlayRoleVoice(passState) -- 角色结算声音
end

---PlayRoleVoice
---角色结算声音
---@param passState number 战斗胜负
function UIBattleEndLeftPanel:PlayRoleVoice(passState)
    local roleData = BattleEndMgr:GetFinalDamageRoleData()
    if not roleData then return end
    local cardVo = CardConfMgr:GetInstance():GetCardByRefId(roleData.cardId)
    if IsNull(cardVo) then
        printError("~__UIBattleEndRoleData Is Null, cardId %s", checkString(roleData.cardId))
        return
    end
    if passState == 1 then
        RoleVoiceMgr:GetInstance():PlayGradeSuccessVoiceByCardId(roleData.cardId, nil, roleData.skinId)
    else
        RoleVoiceMgr:GetInstance():PlayGradeFailedVoiceByCardId(roleData.cardId, nil, roleData.skinId)
    end
end

---ShowType
---Panel展示类型
---@param showType integer @ 展示类型
---@param passState integer @ 关卡通过状态
function UIBattleEndLeftPanel:ShowType(showType, passState)
    if showType == Constants.IDType.QuestGachaCoin then
        ---抽卡道具副本（假象实战）
        self:SetCharactorImg()
        self:ShowPlayerEx()
    elseif showType == Constants.IDType.QuestGachaCoinChallenge or
            showType == Constants.IDType.QuestWorldBoss then
        ---抽卡道具副本挑战(假象实战挑战) && 世界Boss
        self:SetCharactorImg()
    elseif showType == Constants.IDType.QuestTrail then
        --- 试炼副本
        if checkNumber(self.showData.response.score) > 0 then
            self:SetCharactorImg()
        end
    else
        if checkInt(passState) ~= 1 then return end
        if showType == Constants.IDType.QuestMain or
                showType == Constants.IDType.QuestCoinsCopy or
                showType == Constants.IDType.QuestExpCopy or
                showType == Constants.IDType.QuestUpStarCopy then
            self:ShowPlayerEx()
        end
        self:SetCharactorImg()
    end
end

---ShowPlayerEx
---展示玩家经验变化
function UIBattleEndLeftPanel:ShowPlayerEx()
end

---SetCharactorImg
---设置 人物 立绘
function UIBattleEndLeftPanel:SetCharactorImg()
    local roleData = BattleEndMgr:GetFinalDamageRoleData()
    if not roleData then return end
    local roleSkinId = roleData.skinId
    local cardSkinVo = UIBattlingTools.GetCardSkinDataBySkinId(roleSkinId)
    if IsNull(cardSkinVo) then return end
    KTool.SetActive(self.Img_Charactor.gameObject, true)
    self.Img_Charactor:LoadSprite(cardSkinVo.cardDrawing)
end

---SetPlayerExpChangeShow
---展示玩家经验变化
function UIBattleEndLeftPanel:SetPlayerExpChangeShow()
    if IsNull(UIBattlingDataMgr) then return end
    local playerExpBeforeBattleEnd = UIBattlingDataMgr:GetValuePlayExpBeforeBattleEnd()
    if IsNull(playerExpBeforeBattleEnd) or checkInt(playerExpBeforeBattleEnd) >= checkInt(self.showData.response.mainExp) then
        return
    end
    KTool.SetActive(self.Root_PlayerExpInfo.gameObject, true)
    local playerExpNextLv = CardConfMgr:GetInstance():GetPlayerExpByLevelId(checkInt(self.showData.response.playerLv) + 1)
    local playerExpNowLv = CardConfMgr:GetInstance():GetPlayerExpByLevelId(checkInt(self.showData.response.playerLv))
    --- 玩家等级赋值
    self.Txt_LvValue.text = checkString(self.showData.response.playerLv)
    --- 玩家经验 Img
    self.Img_ExpValue.fillAmount = (checkInt(self.showData.response.mainExp) - checkInt(playerExpNowLv.totalExp)) / checkInt(playerExpNextLv.exp)
    --- 玩家经验 process Text
    self.Txt_ExpValueProccess.text = string.format("%d/%d", (checkInt(self.showData.response.mainExp) - checkInt(playerExpNowLv.totalExp)), checkInt(playerExpNextLv.exp))
    --- 玩家经验 text
    self.Txt_ExpValueAdd.text = string.format("EXP+%d", tostring(checkInt(self.showData.response.mainExp) - checkInt(playerExpBeforeBattleEnd)))
end

return UIBattleEndLeftPanel
